import React,{useEffect,useState} from "react";
import {createRoot} from "react-dom/client";
import "./styles/styles.css";

const API="/api";
const BRAND_LOGO="/assets/valmath-logo.jpg"; const BRAND_ICON="/assets/valmath-icon.jpg";
const fallbackImages:{[key:string]:string[]}={services:["https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=80","https://images.unsplash.com/photo-1553877522-43269d4ea984?auto=format&fit=crop&w=900&q=80"],solutions:["https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=80","https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=900&q=80"],industries:["https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=900&q=80","https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=900&q=80"],"case-studies":["https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=900&q=80","https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=80"],insights:["https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=900&q=80","https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=80"]};


async function apiFetch(input: RequestInfo | URL, init: RequestInit = {}, timeout = 8000) {
 const controller = new AbortController();
 const timer = window.setTimeout(() => controller.abort(), timeout);
 try {
  return await fetch(input, { ...init, signal: controller.signal });
 } finally {
  window.clearTimeout(timer);
 }
}
const nav=[["Services","/services/"],["Solutions","/solutions/"],["Industries","/industries/"],["SAP Expertise","/sap-expertise/"],["Approach","/approach/"],["Insights","/insights/"],["About","/about/"]];
const outcomes=[["Modernize","Modernize legacy SAP landscapes."],["Integrate","Connect SAP with the wider enterprise ecosystem."],["Optimize","Improve business processes and system performance."],["Scale","Build scalable enterprise architecture."],["Operate","Keep SAP reliable through structured support and managed services."],["Innovate","Use BTP, data, automation, and AI where they create measurable value."]];

function Header(){const [open,setOpen]=useState(false);return <header id="site-header" className="sticky top-0 z-[200] border-b border-gray-200 bg-white/95 backdrop-blur"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 sm:px-6"><a href="/" className="flex shrink-0 items-center" aria-label="Valmath Consulting home"><img src={BRAND_LOGO} alt="Valmath Consulting" className="h-9 w-auto max-w-[190px] object-contain sm:h-11 sm:max-w-[235px]" /></a><nav className="hidden items-center gap-1 lg:flex" aria-label="Primary">{nav.map(([label,url])=><a key={url} href={url} className="rounded-md px-3 py-2 text-sm font-medium text-ink transition-colors hover:text-accent">{label}</a>)}</nav><a className="hidden rounded-md bg-accent px-5 py-2.5 text-sm font-medium text-white hover:bg-accent-dark lg:block" href="/contact/">Talk to an SAP Expert</a><button id="mobile-menu-toggle" onClick={()=>setOpen(!open)} className="relative z-[220] flex h-11 w-11 items-center justify-center rounded-md bg-transparent text-navy-950 lg:hidden" aria-expanded={open} aria-label={open?"Close navigation menu":"Open navigation menu"}><span className="text-2xl">{open?"×":"☰"}</span></button></div>{open&&<aside className="fixed inset-y-0 right-0 z-[150] flex h-[100dvh] w-[min(88vw,390px)] flex-col overflow-y-auto border-l border-gray-200 bg-white px-6 pb-8 pt-24 shadow-2xl lg:hidden"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-gray-500">Navigation</p><p className="mt-2 text-sm leading-6 text-ink/65">Explore our SAP services, solutions and expertise.</p><nav className="mt-6 flex flex-col">{nav.map(([label,url])=><a key={url} href={url} onClick={()=>setOpen(false)} className="border-b border-gray-200 py-4 text-base font-medium text-navy-950 hover:text-accent">{label}</a>)}</nav><a href="/contact/" className="mt-auto rounded-md bg-accent px-5 py-3 text-center text-sm font-medium text-white">Talk to an SAP Expert</a></aside>}</header>}

function Footer(){return <footer className="border-t border-gray-200 bg-navy-950 text-white"><div className="mx-auto max-w-7xl px-5 py-16 sm:px-6 md:py-20"><div className="grid gap-10 md:grid-cols-12"><div className="md:col-span-4"><a href="/" className="inline-flex items-center" aria-label="Valmath Consulting home"><img src={BRAND_ICON} alt="" className="h-12 w-12 rounded-xl object-cover" /></a><p className="mt-4 max-w-sm text-sm leading-6 text-white/65">SAP consulting for transformation, integration, development, data and managed services. Clear advice, practical delivery.</p><a href="/contact/" className="mt-6 inline-flex text-sm font-semibold hover:text-white/80">Start a conversation →</a></div><div className="md:col-span-8"><div className="grid grid-cols-2 gap-8 sm:grid-cols-3 lg:grid-cols-4">{nav.map(([label,url])=><div key={url}><p className="text-sm font-semibold">{label}</p><a href={url} className="mt-4 block text-sm text-white/60 hover:text-white">Explore {label}</a></div>)}</div></div></div><div className="mt-14 border-t border-white/10 pt-7 text-xs text-white/45">© {new Date().getFullYear()} Valmath Consulting. All rights reserved.</div></div></footer>}

function Layout({children,title,description}:{children:React.ReactNode,title?:string,description?:string}){useEffect(()=>{document.title=title||"Valmath Consulting | SAP Consulting";let m=document.querySelector('meta[name="description"]');if(!m){m=document.createElement("meta");m.setAttribute("name","description");document.head.appendChild(m)}m.setAttribute("content",description||"SAP consulting, S/4HANA transformation, integration, development and managed services for enterprise SAP landscapes.")},[title,description]);return <><Header/><main id="main-content">{children}</main><Footer/></>}

function CTA(){return <section className="bg-navy-950 text-white"><div className="mx-auto max-w-7xl px-5 py-16 sm:px-6 md:py-20"><div className="max-w-3xl"><p className="text-sm font-semibold uppercase tracking-[0.16em] text-white/60">Start a conversation</p><h2 className="mt-3 text-3xl font-semibold tracking-tight md:text-4xl">Have an SAP challenge to solve?</h2><p className="mt-4 text-base leading-7 text-white/70">Tell us what you're trying to solve and we'll follow up with the right SAP specialist.</p><a href="/contact/" className="mt-7 inline-flex rounded-md bg-white px-5 py-3 text-sm font-semibold text-navy-950 hover:bg-gray-50">Talk to an SAP Expert →</a></div></div></section>}

